<template>
  <q-card style="width: 500px; max-width: 1060px; height: auto">
    <q-card-section>
      <div class="row items-center q-pb-none">
        <div data-cy="select-integration" class="text-h6">
          <b>{{ data.title }}</b>
        </div>
        <q-space />
        <q-btn
          icon="close"
          flat
          round
          dense
          v-close-popup
          @click="selectionPopupClosed"
        />
      </div>

      <div style="width: 100%; padding-left: 30px; padding-top: 5px">
        <q-icon class="text-red" style="font-size: 18px" name="warning" />
        <span style="padding-left: 5px">
          {{ $t('selection_popup_origin_warning') }}
        </span>
      </div>

      <template v-if="data.value_2.message">
        <div style="width: 100%; padding-left: 30px; padding-top: 5px">
          <q-icon class="text-red" style="font-size: 18px" name="warning" />
          <span style="padding-left: 5px">
            {{ data.value_2.message }}
          </span>
        </div>
      </template>

      <div style="display: flex; justify-content: center">
        <div
          class="rectangle"
          :class="data.value_1.disable ? 'disable' : ''"
          @click="selectedValue(data.value_1.key, data.value_1.disable)"
        >
          <div style="margin-top: 50px">
            <q-btn
              style="margin-bottom: 25px; pointer-events: none"
              size="25px"
              flat
            >
              {{ data.value_1.value }}
            </q-btn>
          </div>
          <span style="letter-spacing: 1px">{{ data.value_1.label }}</span>
        </div>

        <div
          class="rectangle"
          :class="data.value_2.disable ? 'disable' : ''"
          @click="selectedValue(data.value_2.key, data.value_2.disable)"
        >
          <div style="margin-top: 50px">
            <q-btn
              style="margin-bottom: 25px; pointer-events: none"
              size="25px"
              flat
            >
              {{ data.value_2.value }}
            </q-btn>
          </div>
          <span style="letter-spacing: 1px">{{ data.value_2.label }}</span>
        </div>
      </div>
    </q-card-section>
  </q-card>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';

export default defineComponent({
  name: 'selection-popup',
  props: {
    data: [] as any,
    warning_text: {
      type: String,
    },
  },
  data() {
    return {};
  },
  methods: {
    selectedValue(value: string, disable: boolean) {
      if (disable) {
        return;
      }
      const event = new CustomEvent('selection_popup_selected', {
        detail: { data: this.data, selected: value },
      });
      document.dispatchEvent(event);
    },
    selectionPopupClosed() {
      const event = new CustomEvent('selection_popup_closed', {});
      document.dispatchEvent(event);
    },
  },
});
</script>

<style scoped>
.rectangle {
  height: 200px;
  width: 200px;
  margin: 0 25px 0 25px;
  border: 1px solid #e4e4e4;
  border-radius: 10px;
  text-align: center;
}

.rectangle:hover {
  opacity: 0.7;
  cursor: pointer;
}

.rectangle.disable {
  opacity: 0.7;
  cursor: default;
}
</style>
