import { fieldRulesApiService } from 'src/services/document/FieldRulesApiService';
import type { dynamicObj } from 'src/pages/assets';

export type FieldClearOutcome =
  | 'saved'
  | 'no_extraction_key'
  | 'forbidden'
  | 'failed';

/**
 * Tell the backend that this header field is empty for this layout, so the
 * extraction leaves it blank from now on. Called straight from the "x" — the
 * user must not have to train anything or press "Save Rules" for the cleared
 * field to stick.
 *
 * Never throws: a failure only means the field is blank on this document
 * alone, which is what the caller already applied locally.
 */
export async function persistFieldClear(
  docId: string,
  fieldName: string,
): Promise<FieldClearOutcome> {
  try {
    const response = await fieldRulesApiService.clearFieldRules(docId, [
      fieldName,
    ]);
    if (response?.success === true) {
      return 'saved';
    }
    if (response?.message === 'no_extraction_key') {
      return 'no_extraction_key';
    }
    return 'failed';
  } catch (error: any) {
    if (error?.response?.status === 403) {
      return 'forbidden';
    }
    return 'failed';
  }
}

/**
 * Blank a header field in the view models. Deliberately does NOT stage the
 * name in `record.clear_rules_fields_for_user`: that list is re-sent on every
 * later "Save Rules", where the backend finds the stored suppression and
 * deletes it again — undoing the "x". A name left there by an older session is
 * removed, so a later save cannot undo what `persistFieldClear` stored.
 */
export function clearFieldLocally(
  record: dynamicObj,
  formBuilderModel: dynamicObj,
  fieldName: string,
): void {
  if (Array.isArray(record.fields)) {
    record.fields.forEach((value: dynamicObj, index: number) => {
      if (value.name === fieldName) {
        record.fields.splice(index, 1);
      }
    });
  }

  if (Array.isArray(record.clear_rules_fields_for_user)) {
    record.clear_rules_fields_for_user =
      record.clear_rules_fields_for_user.filter(
        (name: string) => name !== fieldName,
      );
  }

  formBuilderModel[fieldName] = Object.assign(
    formBuilderModel[fieldName] || {},
    {
      deleted: true,
      color: null,
      value: '',
      confidence: 0,
      formatted_value: '',
      content: null,
      validation_code: null,
      coords: null,
    },
  );
}
