import { api } from 'pages/APIs';
import AbstractApiService from 'src/services/abstractApiService';

/**
 * Header-field rule suppression. The "x" next to a header field means "there
 * is nothing here", so the suppression is stored per field on its own — the
 * user must not have to train anything or press "Save Rules" for it to stick.
 */
export default class FieldRulesApiService extends AbstractApiService {
  public constructor() {
    super({});
  }

  public async clearFieldRules(
    docId: string,
    fieldNames: string[],
  ): Promise<any> {
    const formData = new FormData();
    formData.append('doc_id', docId);
    formData.append('fields', JSON.stringify(fieldNames));

    return super.post(api.clear_field_rules, formData);
  }
}

export const fieldRulesApiService: FieldRulesApiService =
  new FieldRulesApiService();
